const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def searchRange(self, nums: List[int], target: int) -> List[int]:", "        l = self.search(nums, target)", "        r = self.search(nums, target + 1)", "        return [-1, -1] if l == r else [l, r - 1]", "", "    def search(self, nums: List[int], x: int) -> int:", "        (left, right) = (0, len(nums))", "        while left < right:", "            mid = (left + right) // 2", "            if nums[mid] >= x:", "                right = mid", "            else:", "                left = mid + 1", "        return left"], "Java": ["import java.util.*;", "class Solution {", "    public int[] searchRange(int[] nums, int target) {", "        int l = search(nums, target);", "        int r = search(nums, target + 1);", "        return l == r ? new int[] {-1, -1} : new int[] {l, r - 1};", "    }", "", "    private int search(int[] nums, int x) {", "        int left = 0, right = nums.length;", "        while (left < right) {", "            int mid = (left + right) >>> 1;", "            if (nums[mid] >= x) {", "                right = mid;", "            } else {", "                left = mid + 1;", "            }", "        }", "        return left;", "    }", "}"]};
